import numpy as np

from bythebook.geometry import apply_T, rotvec_T
from bythebook.kinematics import Chain
from bythebook.registration import solve_registration


def _synthetic(n, noise_mm, seed=0, heights=(0.0,)):
    """Touches on the table generated by a 'true' arm that differs from the nominal model."""
    rng = np.random.default_rng(seed)
    true_off = np.array([0.0, 3.0, -4.0, 2.5, 0.0])
    true_tip = Chain().nominal_tip + np.array([0.004, -0.003, -0.012])
    true = Chain(offsets_deg=true_off, tip_offset=true_tip)
    T = rotvec_T([0.02, -0.01, 1.3], [-0.25, 0.10, 0.012])
    Q, P = [], []
    while len(Q) < n:
        target = np.array([rng.uniform(0.14, 0.30), rng.uniform(-0.13, 0.13), rng.choice(heights)])
        tilt = np.radians(rng.uniform(0, 35))
        az = rng.uniform(-np.pi, np.pi)
        d = np.array([np.sin(tilt) * np.cos(az), np.sin(tilt) * np.sin(az), -np.cos(tilt)])
        r = true.ik(target, d, max_tilt_deg=20)
        if not r.ok:
            continue
        Q.append(r.q_deg)
        P.append(apply_T(T, true.tip(r.q_deg)) + rng.normal(0, noise_mm / 1000.0, 3))
    return np.array(Q), np.array(P), true, T


def test_recovers_exact_model_without_noise():
    Q, P, true, T = _synthetic(16, 0.0)
    reg = solve_registration(Q, P, sigma_mm=0.05)     # trust the data fully
    assert reg.rms_mm < 0.2
    assert reg.loo_rms_mm < 0.5


def test_beats_rigid_only_fit_with_realistic_noise():
    Q, P, true, T = _synthetic(14, 1.0, seed=1)
    full = solve_registration(Q, P)
    rigid = solve_registration(Q, P, fit_tip=False, fit_offsets=False)
    assert full.loo_rms_mm < rigid.loo_rms_mm
    assert full.loo_rms_mm < 3.0

    # What matters: prediction at new poses, here 3 cm above the table (a scale's top face).
    Qn, Pn, _, _ = _synthetic(40, 0.0, seed=2, heights=(0.03,))
    chain = full.chain()
    err = np.linalg.norm(apply_T(full.T, np.array([chain.tip(q) for q in Qn])) - Pn, axis=1) * 1000
    assert np.sqrt(np.mean(err ** 2)) < 3.0, err


def test_few_points_falls_back_to_rigid():
    Q, P, _, _ = _synthetic(5, 0.5, seed=3)
    reg = solve_registration(Q, P)
    assert np.allclose(reg.joint_offsets_deg, 0) and np.allclose(reg.tip_offset, Chain().nominal_tip)
